// CrossValidationTests.swift — Cross-validation against Python Reticulum reference vectors
//
// These tests prove wire compatibility between Swift ReticulumKit and
// Python Reticulum by comparing output for identical inputs.
// Test vectors generated by scripts/generate_test_vectors.py

import Testing
import Foundation
import CryptoKit
@testable import ReticulumKit

/// Cross-validation tests against Python Reticulum reference implementation.
/// Test vectors generated by scripts/generate_test_vectors.py using the
/// same cryptographic algorithms (cryptography library, hashlib, hmac).
@Suite("Cross-Validation: Python Reticulum")
struct CrossValidationTests {

    // MARK: - Helpers

    /// Convert hex string to Data
    private func hexToData(_ hex: String) -> Data {
        var data = Data()
        var hex = hex
        while hex.count >= 2 {
            let byteString = String(hex.prefix(2))
            hex = String(hex.dropFirst(2))
            data.append(UInt8(byteString, radix: 16)!)
        }
        return data
    }

    /// Convert Data to hex string for readable assertion messages
    private func toHex(_ data: Data) -> String {
        data.map { String(format: "%02x", $0) }.joined()
    }

    /// Load a JSON fixture from the test bundle.
    private func loadFixture(_ name: String) throws -> [String: Any] {
        let url = Bundle.module.url(forResource: name, withExtension: "json", subdirectory: "Fixtures")!
        let data = try Data(contentsOf: url)
        return try JSONSerialization.jsonObject(with: data) as! [String: Any]
    }

    /// Extract a nested dictionary from a fixture.
    private func vector(_ fixture: [String: Any], _ key: String) -> [String: Any] {
        fixture[key] as! [String: Any]
    }

    // MARK: - SHA-256

    @Test("SHA-256 full hash matches Python")
    func sha256MatchesPython() throws {
        let fixture = try loadFixture("crypto_vectors")
        let v = vector(fixture, "sha256")
        let input = hexToData(v["input"] as! String)
        let expected = hexToData(v["output"] as! String)

        let result = CryptoEngine.sha256(input)
        #expect(result == expected, "SHA-256: Swift \(toHex(result)) != Python \(toHex(expected))")
    }

    @Test("SHA-256 truncated to 16 bytes matches Python")
    func truncatedHashMatchesPython() throws {
        let fixture = try loadFixture("crypto_vectors")
        let v = vector(fixture, "sha256_truncated_16")
        let input = hexToData(v["input"] as! String)
        let expected = hexToData(v["output"] as! String)

        let result = CryptoEngine.truncatedHash(input)
        #expect(result == expected, "Truncated SHA-256: Swift \(toHex(result)) != Python \(toHex(expected))")
    }

