    // MARK: - Ed25519

    @Test("Ed25519 public key from seed matches Python")
    func ed25519PublicKeyFromSeedMatchesPython() throws {
        let fixture = try loadFixture("crypto_vectors")
        let v = vector(fixture, "ed25519_sign")
        let seed = hexToData(v["seed"] as! String)
        let expectedPubKey = hexToData(v["public_key"] as! String)

        let privateKey = try Curve25519.Signing.PrivateKey(rawRepresentation: seed)
        let publicKeyBytes = Data(privateKey.publicKey.rawRepresentation)
        #expect(publicKeyBytes == expectedPubKey,
                "Ed25519 pubkey: Swift \(toHex(publicKeyBytes)) != Python \(toHex(expectedPubKey))")
    }

    @Test("Ed25519 Python signature verifies in Swift (cross-implementation)")
    func ed25519PythonSignatureVerifiesInSwift() throws {
        // NOTE: Ed25519 signatures are deterministic per RFC 8032, but Apple CryptoKit
        // uses a different internal seed expansion than the Python cryptography library.
        // Both produce VALID signatures, but they are not bit-identical for the same seed.
        // The correct interop test is cross-verification: Python signature must verify
        // in Swift, and Swift signature must verify in Python (validated offline).
        let fixture = try loadFixture("crypto_vectors")
        let v = vector(fixture, "ed25519_sign")
        let seed = hexToData(v["seed"] as! String)
        let message = hexToData(v["message"] as! String)
        let pythonSignature = hexToData(v["signature"] as! String)
        let expectedPubKey = hexToData(v["public_key"] as! String)

        // Verify Python signature using Swift CryptoKit
        let publicKey = try Curve25519.Signing.PublicKey(rawRepresentation: expectedPubKey)
        let isValid = CryptoEngine.verify(
            signature: pythonSignature, message: message, publicKey: publicKey
        )
        #expect(isValid, "Python Ed25519 signature must verify in Swift CryptoKit")

        // Also verify Swift can produce a valid signature that self-verifies
        let privateKey = try Curve25519.Signing.PrivateKey(rawRepresentation: seed)
        let swiftSignature = try CryptoEngine.sign(message, with: privateKey)
        let selfVerify = CryptoEngine.verify(
            signature: swiftSignature, message: message, publicKey: privateKey.publicKey
        )
        #expect(selfVerify, "Swift Ed25519 signature must self-verify")
        #expect(swiftSignature.count == 64, "Ed25519 signature must be 64 bytes")
    }

    // MARK: - Token

    @Test("Token encrypt with fixed IV matches Python")
    func tokenEncryptMatchesPython() throws {
        let fixture = try loadFixture("crypto_vectors")
        let v = vector(fixture, "token_encrypt")
        let key = hexToData(v["key"] as! String)
        let plaintext = hexToData(v["plaintext"] as! String)
        let iv = hexToData(v["iv"] as! String)
        let expectedToken = hexToData(v["token"] as! String)

        // Manually replicate Token.encrypt with fixed IV to match Python
        let token = try Token(key: key)
        // Token uses random IV internally, so we reconstruct manually:
        // signingKey = key[0..<32], encryptionKey = key[32..<64]
        let signingKey = Data(key.prefix(32))
        let encryptionKey = Data(key.suffix(32))
        let ciphertext = try CryptoEngine.aesCBCEncrypt(plaintext, key: encryptionKey, iv: iv)
        let signedParts = iv + ciphertext
        let hmac = CryptoEngine.hmacSHA256(key: signingKey, data: signedParts)
        let result = signedParts + hmac

        #expect(result == expectedToken,
                "Token encrypt: Swift \(toHex(result)) != Python \(toHex(expectedToken))")

        // Also verify that Token.decrypt can round-trip the Python token
        let decrypted = try token.decrypt(expectedToken)
        #expect(decrypted == plaintext,
                "Token decrypt of Python token failed")
    }

    // MARK: - Identity Hash

    @Test("Identity hash matches Python for same key material")
    func identityHashMatchesPython() throws {
        let fixture = try loadFixture("identity_vectors")
        let v = vector(fixture, "identity_1")
        let x25519Seed = hexToData(v["x25519_seed"] as! String)
        let ed25519Seed = hexToData(v["ed25519_seed"] as! String)
        let expectedHash = hexToData(v["identity_hash"] as! String)
        let expectedPubKeyBytes = hexToData(v["public_key_bytes"] as! String)

        // Reconstruct Identity from seed bytes (X25519 + Ed25519 = 64 bytes)
        let privateKeyBytes = x25519Seed + ed25519Seed
        let identity = try Identity(privateKeyBytes: privateKeyBytes)

        // Verify public key bytes match
        #expect(identity.publicKeyBytes == expectedPubKeyBytes,
                "Public key bytes: Swift \(toHex(identity.publicKeyBytes)) != Python \(toHex(expectedPubKeyBytes))")

        // Verify identity hash matches
        #expect(identity.hash.data == expectedHash,
                "Identity hash: Swift \(identity.hash.hexString) != Python \(toHex(expectedHash))")
    }

