    @Test("Announce packet wire bytes match Python")
    func announceWireBytesMatchPython() throws {
        let fixture = try loadFixture("packet_vectors")
        let v = vector(fixture, "announce_minimal")
        let destHash = hexToData(v["destination_hash"] as! String)
        let expectedWire = hexToData(v["wire_bytes"] as! String)

        // Reconstruct announce data payload from components
        let publicKey = hexToData(v["public_key"] as! String)
        let nameHash = hexToData(v["name_hash"] as! String)
        let randomHash = hexToData(v["random_hash"] as! String)
        let signature = hexToData(v["signature"] as! String)
        let announceData = publicKey + nameHash + randomHash + signature

        let header = PacketHeader(
            headerType: .type1,
            propagationType: .broadcast,
            destinationType: .single,
            packetType: .announce,
            hops: UInt8(v["hops"] as! Int)
        )

        let packet = Packet(
            header: header,
            destinationHash: try TruncatedHash(destHash),
            context: .none,
            data: announceData
        )

        let wireBytes = try packet.pack()
        #expect(wireBytes == expectedWire,
                "Announce packet: Swift \(toHex(wireBytes)) != Python \(toHex(expectedWire))")
    }

    @Test("Announce signature verifies with Python-generated signed data")
    func announceSignatureVerifiesPython() throws {
        let pktFixture = try loadFixture("packet_vectors")
        let v = vector(pktFixture, "announce_minimal")
        let signedData = hexToData(v["signed_data"] as! String)
        let signature = hexToData(v["signature"] as! String)

        // Get Ed25519 public key from identity vectors
        let idFixture = try loadFixture("identity_vectors")
        let idVec = vector(idFixture, "identity_1")
        let ed25519Public = hexToData(idVec["ed25519_public"] as! String)

        let publicKey = try Curve25519.Signing.PublicKey(rawRepresentation: ed25519Public)
        let valid = CryptoEngine.verify(signature: signature, message: signedData, publicKey: publicKey)
        #expect(valid, "Python announce signature should verify with Swift CryptoKit")
    }
}
